    let k: Vec<f32> = (0..d).map(|_| rng.gauss()).collect();

    let pairs = [(3usize, 5usize), (7, 9), (100, 102), (1024, 1026)];
    println!(" {:>6}  {:>6}  {:>4}  {:>18}", "pos_q", "pos_k", "gap", "<q_rot, k_rot>");
